import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-BNhko9A9.js";var l=JSON.parse(`{"path":"/product-bundle/cart-checkout-orders.html","title":"Cart, Checkout & Orders","lang":"en-US","frontmatter":{"title":"Cart, Checkout & Orders"},"git":{},"filePathRelative":"product-bundle/cart-checkout-orders.md"}`),u={name:`cart-checkout-orders.md`},d={class:`hint-container tip`};function f(c,l,u,f,p,m){let h=t(`RouteLink`);return s(),o(`div`,null,[l[12]||=n(`<h1 id="cart-checkout-orders" tabindex="-1"><a class="header-anchor" href="#cart-checkout-orders"><span>Cart, Checkout &amp; Orders</span></a></h1><p>A bundle travels through the whole purchase as <strong>one line item that knows its contents</strong>. This page shows each station of that journey — all captured live.</p><h2 id="in-the-cart" tabindex="-1"><a class="header-anchor" href="#in-the-cart"><span>In the cart</span></a></h2><p>The cart shows the bundle as a single line at its calculated bundle price, with every included product listed underneath as &quot;<strong>Included: … x N</strong>&quot;:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/cart-bundle-included.webp" alt="Bundle in the cart"></p>`,5),i(`ul`,null,[l[3]||=i(`li`,null,[e(`Works in both the `),i(`strong`,null,`block cart`),e(` (shown above) and the classic cart shortcode; the classic cart additionally lists the child products under the bundle's name.`)],-1),l[4]||=i(`li`,null,[i(`strong`,null,`Dynamic`),e(` bundles keep their discounted, selection-based price; `),i(`strong`,null,`fixed`),e(` bundles keep the flat price — recalculated server-side on every cart load.`)],-1),i(`li`,null,[l[1]||=e(`Quantity changes in the cart re-run the stock and `,-1),a(h,{to:`/product-bundle/stock-quantity-limits.html#max-purchase-limit`},{default:r(()=>[...l[0]||=[e(`purchase-limit`,-1)]]),_:1}),l[2]||=e(` checks; the block cart's stepper is capped at what is still allowed.`,-1)])]),l[13]||=n(`<h2 id="at-checkout" tabindex="-1"><a class="header-anchor" href="#at-checkout"><span>At checkout</span></a></h2><p>The checkout&#39;s <strong>Order summary</strong> carries the same information — bundle line, price, and the &quot;Included&quot; contents — so customers can confirm exactly what they are buying before paying:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/checkout-bundle-summary.webp" alt="Checkout order summary with a bundle"></p><p>No special payment or shipping configuration is needed; the bundle behaves as one product with one price.</p><h2 id="order-confirmation-and-my-account" tabindex="-1"><a class="header-anchor" href="#order-confirmation-and-my-account"><span>Order confirmation and My Account</span></a></h2><p>On the <strong>order-received</strong> page (and the matching order view under <strong>My Account → Orders</strong>) each bundled product is listed under the bundle line as &quot;<strong>… x N: Included inside bundle</strong>&quot;:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/order-received-bundle.webp" alt="Order received page"></p><h2 id="in-the-admin-order-screen" tabindex="-1"><a class="header-anchor" href="#in-the-admin-order-screen"><span>In the admin order screen</span></a></h2><p>The same contents are stored on the order line item, so <strong>WooCommerce → Orders</strong> shows at a glance what each sold kit contained:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/admin-order-bundle-meta.webp" alt="Admin order line item with bundle contents"></p><p>The line&#39;s price is the final bundle price (after dynamic calculation and discount). Refunds, taxes and totals work on that single line like on any other product line.</p><h2 id="in-order-emails" tabindex="-1"><a class="header-anchor" href="#in-order-emails"><span>In order emails</span></a></h2><p>WooCommerce&#39;s order emails (New Order to the admin, Processing/Completed to the customer, and the rest) render each order line with its visible details — so the bundled products appear under the bundle line as &quot;<em>Included inside bundle</em>&quot; rows, exactly as on the order pages above.</p>`,13),i(`div`,d,[l[8]||=i(`p`,{class:`hint-container-title`},`Fulfilment stays simple`,-1),i(`p`,null,[l[6]||=e(`Warehouse staff see one order line per kit plus its component list — pick the components, pack one kit. Because components are not separate order lines, their own stock is not decremented; see `,-1),a(h,{to:`/product-bundle/stock-quantity-limits.html#how-stock-works`},{default:r(()=>[...l[5]||=[e(`How stock works`,-1)]]),_:1}),l[7]||=e(`.`,-1)])]),i(`p`,null,[l[10]||=e(`Next: some ready-to-copy configurations in `,-1),a(h,{to:`/product-bundle/examples.html`},{default:r(()=>[...l[9]||=[e(`Practical Examples`,-1)]]),_:1}),l[11]||=e(`.`,-1)])])}var p=c(u,[[`render`,f]]);export{l as _pageData,p as default};